R=/scratch/jjyeung/orch_n30
date -u +%TZ
tmux kill-session -t sb_mask_phrase; tmux kill-session -t sb_mask_carry; sleep 3; pgrep -af "agent -p" | grep -c . 
w=sb_mask_phrase; mkdir -p $R/$w/in/v2; echo  | base64 -d | tar xzf - -C $R/$w/in/v2; (cd $R/$w/in/v2 && sha256sum -c --quiet SHA256SUMS && echo v2 OK)
mv $R/$w/cursor.log $R/$w/cursor_stopped_1008Z.log 2>/dev/null; echo  | base64 -d > $R/$w/PROMPT.md
cd $R/$w && tmux new-session -d -s $w "OMP_NUM_THREADS=8 MKL_NUM_THREADS=8 OPENBLAS_NUM_THREADS=8 nice -n 10 timeout 7200 agent -p -f --sandbox disabled --trust --model claude-opus-5-5-xhigh 'Read PROMPT.md in this folder and carry out the task it describes, completely.' > cursor.log 2>&1"
mkdir -p $R/sb_f64rev3/prompts $R/sb_f64rev3/out; echo  | base64 -d > $R/sb_f64rev3/prompts/sb_f64rev3.md; echo sb_f64rev3 >> $R/sb_queue/queue.txt; echo Q: $(cat $R/sb_queue/queue.txt | tr "\n" " ")
sleep 2; tmux ls -F "#{session_name}" | grep "^sb_" | tr "\n" " "; echo
